def unique_jobs(rows):
    seen = set()
    out = []
    for r in rows:
        sid = r.get('source_id')
        if sid is None or (isinstance(sid, str) and sid == ''):
            # Missing/None/empty source_id: keep the row separately.
            out.append(r)
        else:
            key = (r.get('source'), sid)
            if key not in seen:
                seen.add(key)
                out.append(r)
    return out
